```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Keep only items we have not already seen. An item is "seen" when its
        // id is present as a key in the read-only 'seen' store. The store is
        // read-only (state-read exposes only `get`), so this node observes the
        // prior run's record without changing it.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
